<style>
:root{color-scheme:dark;--ink:#f7f2fb;--muted:#b6a9c2;--line:#ffffff1c;--purple:#a277ff;--pink:#ef55bd}*{box-sizing:border-box}html,body{height:100%;margin:0;background:#0b0712;color:var(--ink);font:14px/1.5 system-ui,-apple-system,"Segoe UI",sans-serif}body{display:grid;grid-template-rows:56px 1fr auto;background:radial-gradient(ellipse at 50% -30%,#381650,#0b0712 65%)}.top{display:flex;align-items:center;justify-content:space-between;padding:0 18px;border-bottom:1px solid var(--line);background:#0b0712cc}.brand{display:flex;align-items:center;gap:10px;font-weight:850;letter-spacing:.02em}.mark{display:block;width:36px;height:36px;overflow:hidden;border:1px solid #a277ff99;border-radius:50%;background:#100a17}.mark img{width:100%;height:100%;object-fit:cover;object-position:center 32%}.back{color:#d4b5ff;text-decoration:none;font-size:12px}.feed{overflow:auto;padding:24px 18px 14px}.intro{max-width:650px;margin:auto auto 24px;text-align:center}.intro-avatar{width:104px;height:104px;display:block;object-fit:cover;object-position:center 26%;margin:0 auto 10px;border:1px solid #a277ff88;border-radius:50%;background:#100a17;box-shadow:0 0 34px #a277ff33}.intro h1{margin:8px 0;font-size:clamp(25px,5vw,38px);letter-spacing:-.04em}.intro p{max-width:540px;margin:auto;color:var(--muted)}.pills{display:flex;justify-content:center;gap:7px;flex-wrap:wrap;margin-top:14px}.pills span{padding:5px 9px;border:1px solid var(--line);border-radius:99px;color:#d9cce5;font-size:10px}.messages{max-width:700px;margin:auto}.message{display:grid;grid-template-columns:30px 1fr;gap:10px;margin:15px 0}.avatar{width:30px;height:30px;display:grid;place-items:center;border-radius:10px;background:#241633;font-weight:850;overflow:hidden}.avatar img{width:100%;height:100%;object-fit:cover;object-position:center 32%}.assistant .avatar{border:1px solid #a277ff88;background:#100a17}.bubble{padding:5px 0;white-space:pre-wrap;overflow-wrap:anywhere}.welcome{padding:15px;border:1px solid #ffffff17;border-radius:16px;background:#ffffff08}.welcome b{display:block;margin-bottom:6px}.suggestions{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.suggestions button{padding:8px 10px;border:1px solid #a277ff66;border-radius:10px;color:#f6eaff;background:#a277ff13;cursor:pointer;font-size:11px}.composer-wrap{padding:12px max(16px,calc((100vw - 700px)/2)) max(13px,env(safe-area-inset-bottom));border-top:1px solid var(--line);background:#0b0712ee}.composer{display:grid;grid-template-columns:1fr 42px;align-items:end;gap:8px;padding:8px 8px 8px 13px;border:1px solid #a277ff66;border-radius:15px;background:#140d20}.composer:focus-within{box-shadow:0 0 0 3px #a277ff20}textarea{width:100%;max-height:130px;resize:vertical;border:0;outline:0;color:#fff;background:transparent;font:inherit}textarea::placeholder{color:#92839e}.send{width:40px;height:40px;border:0;border-radius:12px;color:#fff;background:linear-gradient(130deg,var(--purple),var(--pink));font-size:19px;cursor:pointer}.send:disabled{opacity:.5}.fine{margin:7px 0 0;text-align:center;color:#90839c;font-size:9px}.error{color:#ffa2cf;font-size:11px;text-align:center;min-height:16px}.embed .top{padding:0 13px}.embed .feed{padding:16px 13px}.embed .intro{margin-bottom:14px}.embed .intro-avatar{width:54px;height:54px;margin-bottom:4px}.embed .intro h1{font-size:26px}.embed .intro p{font-size:11px}.embed .pills{display:none}.embed .composer-wrap{padding:9px 10px max(9px,env(safe-area-inset-bottom))}.embed .fine{font-size:8px}@media(max-width:480px){.top{padding:0 12px}.feed{padding:16px 12px}.intro h1{font-size:25px}.composer-wrap{padding-inline:10px}}
